import click
from click.testing import CliRunner

def test_argument_choice_metavar():
    @click.command()
    @click.argument("arg", type=click.Choice(["a", "b"]), required=False)
    def cli(arg):
        pass

    runner = CliRunner()
    result = runner.invoke(cli, ["--help"])
    assert "[[a|b]]" not in result.output
    assert "[a|b]" in result.output

import click
from click.testing import CliRunner

def test_optional_choice_metavar():
    @click.command()
    @click.argument("arg", type=click.Choice(["a", "b"]), required=False)
    def cli(arg):
        pass

    runner = CliRunner()
    result = runner.invoke(cli, ["--help"])
    assert result.exit_code == 0
    assert "Usage: cli [OPTIONS] [a|b]" in result.output
